/* Nota Bab 1 T3 (ENGLISH / DLP), terjemahan nota BM. Dijana skrip bina_bab1_t3_en.py; jangan sunting dengan tangan. */
window.SUBS=[{"no": "1.1", "name": "Index Notation", "col": "#FBBF24"}, {"no": "1.2", "name": "Law of Indices", "col": "#A78BFA"}];
window.SLIDES=[{"sub": "1.1", "n": 1, "N": 5, "kicker": "DEFINITION", "title": "Index form", "body": "<p class=\"sl-p\">A number that is multiplied repeatedly can be written in index form.</p><div class=\"sl-def\" style=\"--c:#FBBF24\"><p>The value of the index in an index form is equal to the number of times the base is multiplied repeatedly. In general, <i>a</i><sup><i>n</i></sup> = <i>a</i> × <i>a</i> × <i>a</i> × … × <i>a</i> (<i>n</i> factors); <i>a</i> ≠ 0</p></div><div class=\"sl-note\"><b>Remember:</b> <i>a</i> is the base and <i>n</i> is the index.</div>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;align-items:center;gap:18px;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:30px\"><div style=\"font-size:72px;font-weight:800\"><i>a</i><sup style=\"color:#F472B6\"><i>n</i></sup></div><div style=\"display:flex;gap:40px;font-size:20px\"><span><b style=\"color:#38BDF8\"><i>a</i></b> : base</span><span><b style=\"color:#F472B6\"><i>n</i></b> : index</span></div><div style=\"font-size:22px;font-weight:700\">5<sup>4</sup> = 5 × 5 × 5 × 5</div><div style=\"font-size:16px;color:#B6C2D3\">read as \"5 to the power of 4\"</div></div>", "full": ""}, {"sub": "1.1", "n": 2, "N": 5, "kicker": "EXAMPLE 1", "title": "Writing in index form", "body": "<p class=\"sl-p\">Write the following repeated multiplications in index form.</p><ul class=\"sl-bul\" style=\"--c:#FBBF24\"><li><span>(a) 6 × 6 × 6 × 6</span></li><li><span>(b) (−3) × (−3) × (−3) × (−3) × (−3)</span></li><li><span>(c) 0.2 × 0.2 × 0.2</span></li><li><span>(d) <span class=\"fr\"><span>2</span><span>5</span></span> × <span class=\"fr\"><span>2</span><span>5</span></span> × <span class=\"fr\"><span>2</span><span>5</span></span> × <span class=\"fr\"><span>2</span><span>5</span></span></span></li><li><span>(e) <i>p</i> × <i>p</i> × <i>p</i> × <i>p</i> × <i>p</i> × <i>p</i></span></li><li><span>(f) <i>k</i> × <i>k</i> × … × <i>k</i> (repeated <i>n</i> times)</span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><div class=\"rv\">(a) 6<sup>4</sup> &nbsp; (repeated four times)</div><div class=\"rv\">(b) (−3)<sup>5</sup> &nbsp; (repeated five times)</div><div class=\"rv\">(c) (0.2)<sup>3</sup> &nbsp; (repeated three times)</div><div class=\"rv\">(d) (<span class=\"fr\"><span>2</span><span>5</span></span>)<sup>4</sup> &nbsp; (repeated four times)</div><div class=\"rv\">(e) <i>p</i><sup>6</sup> &nbsp; (repeated six times)</div><div class=\"rv\">(f) <i>k</i><sup><i>n</i></sup></div></div></div>", "full": ""}, {"sub": "1.1", "n": 3, "N": 5, "kicker": "EXAMPLE 2", "title": "Converting a number into index form", "body": "<p class=\"sl-p\">A number can be written in index form if a suitable base is chosen. You can use the repeated division method or the repeated multiplication method to convert a number into a number in index form.</p><p class=\"sl-p\"><b>EXAMPLE 2</b> Write 81 in index form using base 3 and base 9.</p><div class=\"sl-note\"><b>Tip:</b> The division is continued until the value 1 is obtained.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#FBBF24\">Repeated division method (base 3)</b> <div class=\"rv\">81 ÷ 3 = 27, 27 ÷ 3 = 9, 9 ÷ 3 = 3, 3 ÷ 3 = 1</div><div class=\"rv\">81 is divided repeatedly by 3 four times.</div><div class=\"rv\">Hence, 81 = 3<sup>4</sup></div></div><div><b style=\"color:#FBBF24\">Repeated multiplication method (base 3)</b> <div class=\"rv\">3 × 3 = 9, 9 × 3 = 27, 27 × 3 = 81</div><div class=\"rv\">Hence, 81 = 3<sup>4</sup></div></div><div><b style=\"color:#FBBF24\">Base 9</b> <div class=\"rv\">81 ÷ 9 = 9, 9 ÷ 9 = 1  or  9 × 9 = 81</div><div class=\"rv\">Hence, 81 = 9<sup>2</sup></div></div></div>", "full": ""}, {"sub": "1.1", "n": 4, "N": 5, "kicker": "EXAMPLE 3", "title": "Fractions in index form", "body": "<p class=\"sl-p\">Write <span class=\"fr\"><span>27</span><span>125</span></span> in index form using base <span class=\"fr\"><span>3</span><span>5</span></span>.</p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:grid;grid-template-columns:repeat(2,1fr);gap:10px 18px;font-size:19px;line-height:1.5\"><div><b style=\"color:#FBBF24\">Repeated division method</b> <div class=\"rv\">27 ÷ 3 = 9, 9 ÷ 3 = 3, 3 ÷ 3 = 1 (3 times)</div><div class=\"rv\">125 ÷ 5 = 25, 25 ÷ 5 = 5, 5 ÷ 5 = 1 (3 times)</div><div class=\"rv\">Hence, <span class=\"fr\"><span>27</span><span>125</span></span> = (<span class=\"fr\"><span>3</span><span>5</span></span>)<sup>3</sup></div></div><div><b style=\"color:#FBBF24\">Repeated multiplication method</b> <div class=\"rv\"><span class=\"fr\"><span>3</span><span>5</span></span> × <span class=\"fr\"><span>3</span><span>5</span></span> = <span class=\"fr\"><span>9</span><span>25</span></span></div><div class=\"rv\"><span class=\"fr\"><span>9</span><span>25</span></span> × <span class=\"fr\"><span>3</span><span>5</span></span> = <span class=\"fr\"><span>27</span><span>125</span></span></div><div class=\"rv\">Hence, <span class=\"fr\"><span>27</span><span>125</span></span> = (<span class=\"fr\"><span>3</span><span>5</span></span>)<sup>3</sup></div></div></div><div class=\"sl-note\"><b>Remember:</b> For fractions, the numerator and the denominator are divided or multiplied repeatedly the same number of times.</div>", "fig": "", "full": ""}, {"sub": "1.1", "n": 5, "N": 5, "kicker": "EXAMPLE 4", "title": "Value of a number in index form", "body": "<p class=\"sl-p\">The value of <i>a</i><sup><i>n</i></sup> can be determined by the repeated multiplication method or by using a scientific calculator.</p><p class=\"sl-p\"><b>EXAMPLE 4</b> Calculate the value of each given number in index form. (a) 3<sup>4</sup> (b) (0.4)<sup>3</sup></p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:grid;grid-template-columns:repeat(2,1fr);gap:10px 18px;font-size:19px;line-height:1.5\"><div><b style=\"color:#FBBF24\">(a)</b> <div class=\"rv\">3<sup>4</sup> = 3 × 3 × 3 × 3</div><div class=\"rv\">= 9 × 9</div><div class=\"rv\">Hence, 3<sup>4</sup> = 81</div></div><div><b style=\"color:#FBBF24\">(b)</b> <div class=\"rv\">(0.4)<sup>3</sup> = 0.4 × 0.4 × 0.4</div><div class=\"rv\">= 0.16 × 0.4</div><div class=\"rv\">Hence, (0.4)<sup>3</sup> = 0.064</div></div></div><div class=\"sl-note\"><b>Reminder:</b> Negative bases and fractional bases are written with brackets when using a calculator to determine the value of the number.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><b style=\"color:#FBBF24\">EXAMPLE 5</b> <div class=\"rv\">Calculate the value of each number in index form using a calculator.</div></div><div><div class=\"rv\">(a) 4<sup>5</sup> = 1 024</div><div class=\"rv\">(b) (−2)<sup>7</sup> = −128</div><div class=\"rv\">(c) (<span class=\"fr\"><span>3</span><span>4</span></span>)<sup>3</sup> = <span class=\"fr\"><span>27</span><span>64</span></span></div><div class=\"rv\">(d) (1<span class=\"fr\"><span>1</span><span>2</span></span>)<sup>4</sup> = <span class=\"fr\"><span>81</span><span>16</span></span></div><div class=\"rv\">(e) (−0.3)<sup>4</sup> = 0.0081</div></div></div>", "full": ""}, {"sub": "1.2", "n": 1, "N": 17, "kicker": "LAW", "title": "Multiplication of numbers in index form", "body": "<p class=\"sl-p\">What is the relationship between the multiplication of numbers in index form with the same base and repeated multiplication?</p><p class=\"sl-p\">In general,</p><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #A78BFA;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\"><i>a</i><sup><i>m</i></sup> × <i>a</i><sup><i>n</i></sup> = <i>a</i><sup><i>m</i> + <i>n</i></sup></div><div class=\"sl-note\"><b>Tip:</b> Group the numbers or algebraic terms with the same base first. Then, add the indices of the same base.</div>", "fig": "<div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:16px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Multiplication of numbers in index form</th><th style=\"padding:7px 10px;text-align:center;font-size:16px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Repeated multiplication</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">2<sup>3</sup> × 2<sup>4</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">(2 × 2 × 2) × (2 × 2 × 2 × 2) = 2<sup>7</sup> = 2<sup>3 + 4</sup></td></tr><tr class=\"rv\"><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">3<sup>2</sup> × 3<sup>3</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">(3 × 3) × (3 × 3 × 3) = 3<sup>5</sup> = 3<sup>2 + 3</sup></td></tr><tr class=\"rv\"><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">5<sup>4</sup> × 5<sup>2</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">(5 × 5 × 5 × 5) × (5 × 5) = 5<sup>6</sup> = 5<sup>4 + 2</sup></td></tr></tbody></table></div>", "full": ""}, {"sub": "1.2", "n": 2, "N": 17, "kicker": "EXAMPLE 6", "title": "Law of multiplication", "body": "<p class=\"sl-p\">Simplify each of the following. (a) 5<sup>3</sup> × 5<sup>4</sup> (b) (0.3)<sup>2</sup> × (0.3)<sup>5</sup> × (0.3) (c) 3<i>k</i><sup>2</sup> × 4<i>k</i><sup>3</sup> (d) 2<i>m</i><sup>4</sup> × <span class=\"fr\"><span>1</span><span>4</span></span><i>m</i><sup>2</sup> × 6<i>m</i></p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:grid;grid-template-columns:repeat(2,1fr);gap:10px 18px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">5<sup>3</sup> × 5<sup>4</sup> = 5<sup>3 + 4</sup></div><div class=\"rv\">= 5<sup>7</sup></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">(0.3)<sup>2</sup> × (0.3)<sup>5</sup> × (0.3)<sup>1</sup> = (0.3)<sup>2 + 5 + 1</sup></div><div class=\"rv\">= (0.3)<sup>8</sup></div></div><div><b style=\"color:#A78BFA\">(c)</b> <div class=\"rv\">3<i>k</i><sup>2</sup> × 4<i>k</i><sup>3</sup> = (3 × 4)<i>k</i><sup>2 + 3</sup></div><div class=\"rv\">= 12<i>k</i><sup>5</sup></div></div><div><b style=\"color:#A78BFA\">(d)</b> <div class=\"rv\">(2 × <span class=\"fr\"><span>1</span><span>4</span></span> × 6)<i>m</i><sup>4 + 2 + 1</sup></div><div class=\"rv\">= 3<i>m</i><sup>7</sup></div></div></div><div class=\"sl-note\"><b>Reminder:</b> <i>a</i> = <i>a</i><sup>1</sup></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">EXAMPLE 7</b> <div class=\"rv\">Simplify each of the following. (a) <i>m</i><sup>3</sup> × <i>n</i><sup>2</sup> × <i>m</i><sup>4</sup> × <i>n</i> (b) (0.2)<sup>3</sup> × (0.5)<sup>2</sup> × (0.2) × (0.5)<sup>4</sup></div></div><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= <i>m</i><sup>3</sup> × <i>m</i><sup>4</sup> × <i>n</i><sup>2</sup> × <i>n</i><sup>1</sup></div><div class=\"rv\">= <i>m</i><sup>3 + 4</sup> × <i>n</i><sup>2 + 1</sup></div><div class=\"rv\">= <i>m</i><sup>7</sup><i>n</i><sup>3</sup></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= (0.2)<sup>3</sup> × (0.2)<sup>1</sup> × (0.5)<sup>2</sup> × (0.5)<sup>4</sup></div><div class=\"rv\">= (0.2)<sup>3 + 1</sup> × (0.5)<sup>2 + 4</sup></div><div class=\"rv\">= (0.2)<sup>4</sup> × (0.5)<sup>6</sup></div></div></div>", "full": ""}, {"sub": "1.2", "n": 3, "N": 17, "kicker": "LAW", "title": "Division of numbers in index form", "body": "<p class=\"sl-p\">What is the relationship between the division of numbers in index form with the same base and repeated multiplication?</p><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Division</th><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Repeated multiplication</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">4<sup>5</sup> ÷ 4<sup>2</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\"><span class=\"fr\"><span>4 × 4 × 4 × 4 × 4</span><span>4 × 4</span></span> = 4<sup>3</sup> = 4<sup>5 − 2</sup></td></tr><tr class=\"rv\"><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">2<sup>6</sup> ÷ 2<sup>2</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\"><span class=\"fr\"><span>2 × 2 × 2 × 2 × 2 × 2</span><span>2 × 2</span></span> = 2<sup>4</sup> = 2<sup>6 − 2</sup></td></tr></tbody></table></div><p class=\"sl-p\">In general,</p><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #A78BFA;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\"><i>a</i><sup><i>m</i></sup> ÷ <i>a</i><sup><i>n</i></sup> = <i>a</i><sup><i>m</i> − <i>n</i></sup></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#A78BFA\">EXAMPLE 8</b> <div class=\"rv\">Simplify each of the following. (a) 6<sup>7</sup> ÷ 6<sup>3</sup> (b) (−2)<sup>8</sup> ÷ (−2)<sup>5</sup> (c) <i>p</i><sup>9</sup> ÷ <i>p</i><sup>4</sup> (d) 20<i>x</i><sup>6</sup><i>y</i><sup>5</sup> ÷ 4<i>x</i><sup>2</sup><i>y</i><sup>3</sup></div></div><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= 6<sup>7 − 3</sup> = 6<sup>4</sup></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= (−2)<sup>8 − 5</sup> = (−2)<sup>3</sup> = −8</div></div><div><b style=\"color:#A78BFA\">(c)</b> <div class=\"rv\">= <i>p</i><sup>9 − 4</sup> = <i>p</i><sup>5</sup></div></div><div><b style=\"color:#A78BFA\">(d)</b> <div class=\"rv\">= <span class=\"fr\"><span>20</span><span>4</span></span> × <i>x</i><sup>6 − 2</sup> × <i>y</i><sup>5 − 3</sup></div><div class=\"rv\">= 5<i>x</i><sup>4</sup><i>y</i><sup>2</sup></div></div></div>", "full": ""}, {"sub": "1.2", "n": 4, "N": 17, "kicker": "LAW", "title": "Power of a number in index form", "body": "<div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Index form raised to a power</th><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Repeated multiplication</th><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Conclusion</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">(3<sup>2</sup>)<sup>4</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">3<sup>2</sup> × 3<sup>2</sup> × 3<sup>2</sup> × 3<sup>2</sup> = 3<sup>2 + 2 + 2 + 2</sup> = 3<sup>8</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">(3<sup>2</sup>)<sup>4</sup> = 3<sup>2(4)</sup></td></tr><tr class=\"rv\"><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">(5<sup>4</sup>)<sup>3</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">5<sup>4</sup> × 5<sup>4</sup> × 5<sup>4</sup> = 5<sup>4 + 4 + 4</sup> = 5<sup>12</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">(5<sup>4</sup>)<sup>3</sup> = 5<sup>4(3)</sup></td></tr></tbody></table></div><p class=\"sl-p\">In general,</p><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #A78BFA;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\">(<i>a</i><sup><i>m</i></sup>)<sup><i>n</i></sup> = <i>a</i><sup><i>mn</i></sup></div><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #A78BFA;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\">(<i>a</i><sup><i>m</i></sup><i>b</i><sup><i>n</i></sup>)<sup><i>p</i></sup> = <i>a</i><sup><i>mp</i></sup><i>b</i><sup><i>np</i></sup> &nbsp; ; &nbsp; (<span class=\"fr\"><span><i>a</i><sup><i>m</i></sup></span><span><i>b</i><sup><i>n</i></sup></span></span>)<sup><i>p</i></sup> = <span class=\"fr\"><span><i>a</i><sup><i>mp</i></sup></span><span><i>b</i><sup><i>np</i></sup></span></span></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">EXAMPLE 9</b> <div class=\"rv\">1. Simplify: (a) (3<sup>4</sup>)<sup>2</sup> (b) (<i>k</i><sup>5</sup>)<sup>3</sup> (c) ((−<i>y</i>)<sup>2</sup>)<sup>4</sup></div></div><div><b style=\"color:#A78BFA\">Solution:</b> <div class=\"rv\">(a) 3<sup>4(2)</sup> = 3<sup>8</sup> &nbsp; (b) <i>k</i><sup>5(3)</sup> = <i>k</i><sup>15</sup> &nbsp; (c) (−<i>y</i>)<sup>2(4)</sup> = (−<i>y</i>)<sup>8</sup> = <i>y</i><sup>8</sup></div></div><div><div class=\"rv\">2. Determine whether the equation (2<sup>3</sup>)<sup>4</sup> = (2<sup>4</sup>)<sup>3</sup> is true or false.</div></div><div><b style=\"color:#A78BFA\">Solution:</b> <div class=\"rv\">Left: (2<sup>3</sup>)<sup>4</sup> = 2<sup>12</sup>. Right: (2<sup>4</sup>)<sup>3</sup> = 2<sup>12</sup></div><div class=\"rv\">Hence, (2<sup>3</sup>)<sup>4</sup> = (2<sup>4</sup>)<sup>3</sup> is true.</div></div></div>", "full": ""}, {"sub": "1.2", "n": 5, "N": 17, "kicker": "EXAMPLE 10", "title": "Laws of indices in multiplication and division", "body": "<p class=\"sl-p\">Simplify each of the following. (a) (5<sup>3</sup> × 7<sup>2</sup>)<sup>4</sup> (b) (2<sup>3</sup> × 3<sup>2</sup> × 11<sup>5</sup>)<sup>2</sup> (c) (<span class=\"fr\"><span>2<i>x</i><sup>3</sup></span><span>3<i>y</i><sup>2</sup></span></span>)<sup>4</sup> (d) <span class=\"fr\"><span>(4<i>m</i><sup>3</sup><i>n</i><sup>2</sup>)<sup>2</sup></span><span>8<i>m</i><sup>4</sup><i>n</i></span></span></p><div class=\"sl-note\"><b>Recall:</b> (<i>a</i><sup><i>m</i></sup> × <i>b</i><sup><i>n</i></sup>)<sup><i>p</i></sup> = <i>a</i><sup><i>mp</i></sup> × <i>b</i><sup><i>np</i></sup></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:grid;grid-template-columns:repeat(2,1fr);gap:10px 18px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= 5<sup>3(4)</sup> × 7<sup>2(4)</sup></div><div class=\"rv\">= 5<sup>12</sup> × 7<sup>8</sup></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= 2<sup>3(2)</sup> × 3<sup>2(2)</sup> × 11<sup>5(2)</sup></div><div class=\"rv\">= 2<sup>6</sup> × 3<sup>4</sup> × 11<sup>10</sup></div></div><div><b style=\"color:#A78BFA\">(c)</b> <div class=\"rv\">= <span class=\"fr\"><span>2<sup>4</sup><i>x</i><sup>3(4)</sup></span><span>3<sup>4</sup><i>y</i><sup>2(4)</sup></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>16<i>x</i><sup>12</sup></span><span>81<i>y</i><sup>8</sup></span></span></div></div><div><b style=\"color:#A78BFA\">(d)</b> <div class=\"rv\">= <span class=\"fr\"><span>4<sup>2</sup><i>m</i><sup>3(2)</sup><i>n</i><sup>2(2)</sup></span><span>8<i>m</i><sup>4</sup><i>n</i></span></span> = <span class=\"fr\"><span>16<i>m</i><sup>6</sup><i>n</i><sup>4</sup></span><span>8<i>m</i><sup>4</sup><i>n</i><sup>1</sup></span></span></div><div class=\"rv\">= 2<i>m</i><sup>6 − 4</sup><i>n</i><sup>4 − 1</sup> = 2<i>m</i><sup>2</sup><i>n</i><sup>3</sup></div></div></div>", "full": ""}, {"sub": "1.2", "n": 6, "N": 17, "kicker": "LAW", "title": "Zero index and negative index", "body": "<div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Division</th><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Law of indices</th><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Repeated multiplication</th><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Conclusion</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">2<sup>3</sup> ÷ 2<sup>3</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">2<sup>3 − 3</sup> = 2<sup>0</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\"><span class=\"fr\"><span>2 × 2 × 2</span><span>2 × 2 × 2</span></span> = 1</td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">2<sup>0</sup> = 1</td></tr><tr class=\"rv\"><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">2<sup>3</sup> ÷ 2<sup>5</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">2<sup>3 − 5</sup> = 2<sup>−2</sup></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\"><span class=\"fr\"><span>2 × 2 × 2</span><span>2 × 2 × 2 × 2 × 2</span></span> = <span class=\"fr\"><span>1</span><span>2<sup>2</sup></span></span></td><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\">2<sup>−2</sup> = <span class=\"fr\"><span>1</span><span>2<sup>2</sup></span></span></td></tr></tbody></table></div><div class=\"sl-def\" style=\"--c:#A78BFA\"><p>Any number or algebraic term with a zero index has a value of 1.</p></div><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #A78BFA;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\"><i>a</i><sup>0</sup> = 1 ; <i>a</i> ≠ 0 &nbsp;&nbsp;&nbsp; <i>a</i><sup>−<i>n</i></sup> = <span class=\"fr\"><span>1</span><span><i>a</i><sup><i>n</i></sup></span></span> ; <i>a</i> ≠ 0</div><div class=\"sl-note\"><b>Tip:</b> A negative index is the index of a number or algebraic term that has a negative value. (<span class=\"fr\"><span><i>a</i></span><span><i>b</i></span></span>)<sup>−<i>n</i></sup> = (<span class=\"fr\"><span><i>b</i></span><span><i>a</i></span></span>)<sup><i>n</i></sup></div>", "fig": "", "full": ""}, {"sub": "1.2", "n": 7, "N": 17, "kicker": "EXAMPLE 11", "title": "Negative indices", "body": "<p class=\"sl-p\">1. State each of the following terms in positive index form. (a) <i>a</i><sup>−3</sup> (b) <i>x</i><sup>−5</sup> (c) <span class=\"fr\"><span>1</span><span>9<sup>−2</sup></span></span> (d) 4<i>m</i><sup>−6</sup> (e) (<span class=\"fr\"><span>3</span><span>7</span></span>)<sup>−4</sup></p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><div class=\"rv\">(a) <i>a</i><sup>−3</sup> = <span class=\"fr\"><span>1</span><span><i>a</i><sup>3</sup></span></span></div><div class=\"rv\">(b) <i>x</i><sup>−5</sup> = <span class=\"fr\"><span>1</span><span><i>x</i><sup>5</sup></span></span></div><div class=\"rv\">(c) <span class=\"fr\"><span>1</span><span>9<sup>−2</sup></span></span> = 9<sup>2</sup></div><div class=\"rv\">(d) 4<i>m</i><sup>−6</sup> = <span class=\"fr\"><span>4</span><span><i>m</i><sup>6</sup></span></span></div><div class=\"rv\">(e) (<span class=\"fr\"><span>3</span><span>7</span></span>)<sup>−4</sup> = (<span class=\"fr\"><span>7</span><span>3</span></span>)<sup>4</sup></div></div></div><p class=\"sl-p\">2. Simplify <span class=\"fr\"><span>5<sup>2</sup> × 5<sup>3</sup></span><span>5<sup>8</sup></span></span>.</p>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><b style=\"color:#A78BFA\">Solution 2:</b> <div class=\"rv\">= 5<sup>2 + 3 − 8</sup></div><div class=\"rv\">= 5<sup>−3</sup></div><div class=\"rv\">= <span class=\"fr\"><span>1</span><span>5<sup>3</sup></span></span></div></div></div><div class=\"sl-note\"><b>Reminder:</b> 2<i>a</i><sup>−1</sup> ≠ <span class=\"fr\"><span>1</span><span>2<i>a</i></span></span></div></div>", "full": ""}, {"sub": "1.2", "n": 8, "N": 17, "kicker": "LAW", "title": "Fractional indices", "body": "<p class=\"sl-p\">In Form 1, you learned about squares and square roots as well as cubes and cube roots. Did you know that the value of <i>x</i> in <i>x</i><sup>2</sup> = 9 and <i>x</i><sup>3</sup> = 64 can be determined by raising the index to the power of its reciprocal?</p><p class=\"sl-p\">In general,</p><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #A78BFA;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\"><span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i></span></span> = <i>a</i><sup><span class=\"fr\"><span>1</span><span><i>n</i></span></span></sup> ; <i>a</i> ≠ 0</div><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #A78BFA;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\"><i>a</i><sup><span class=\"fr\"><span><i>m</i></span><span><i>n</i></span></span></sup> = (<i>a</i><sup><i>m</i></sup>)<sup><span class=\"fr\"><span>1</span><span><i>n</i></span></span></sup> = (<i>a</i><sup><span class=\"fr\"><span>1</span><span><i>n</i></span></span></sup>)<sup><i>m</i></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i><sup><i>m</i></sup></span></span> = (<span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i></span></span>)<sup><i>m</i></sup></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\"><i>x</i><sup>2</sup> = 9</div><div class=\"rv\">(<i>x</i><sup>2</sup>)<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup> = 9<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup></div><div class=\"rv\"><i>x</i> = (3<sup>2</sup>)<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup> = 3</div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\"><i>x</i><sup>3</sup> = 64</div><div class=\"rv\">(<i>x</i><sup>3</sup>)<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> = 64<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup></div><div class=\"rv\"><i>x</i> = (4<sup>3</sup>)<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> = 4</div></div></div>", "full": ""}, {"sub": "1.2", "n": 9, "N": 17, "kicker": "EXAMPLE 12", "title": "Converting between fractional indices and roots", "body": "<p class=\"sl-p\">1. Convert each of the following terms into the form <i>a</i><sup><span class=\"fr\"><span>1</span><span><i>n</i></span></span></sup>. (a) <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">2</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">36</span></span> (b) <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">3</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">−27</span></span> (c) <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">5</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>m</i></span></span></p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><div class=\"rv\">(a) <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">2</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">36</span></span> = 36<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup> &nbsp; (b) <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">3</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">−27</span></span> = (−27)<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> &nbsp; (c) <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">5</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>m</i></span></span> = <i>m</i><sup><span class=\"fr\"><span>1</span><span>5</span></span></sup></div></div></div><p class=\"sl-p\">2. Convert each of the following terms into the form <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i></span></span>. (a) 1024<sup><span class=\"fr\"><span>1</span><span>5</span></span></sup> (b) 64<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> (c) <i>k</i><sup><span class=\"fr\"><span>1</span><span>7</span></span></sup></p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><div class=\"rv\">(a) 1024<sup><span class=\"fr\"><span>1</span><span>5</span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">5</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">1 024</span></span> &nbsp; (b) 64<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">3</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">64</span></span> &nbsp; (c) <i>k</i><sup><span class=\"fr\"><span>1</span><span>7</span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">7</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>k</i></span></span></div></div></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><b style=\"color:#A78BFA\">3. Calculate the value of each of the following.</b> <div class=\"rv\">(a) <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">5</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">32</span></span> = (2<sup>5</sup>)<sup><span class=\"fr\"><span>1</span><span>5</span></span></sup> = 2<sup>1</sup> = 2</div><div class=\"rv\">(b) <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">3</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">64</span></span> = (4<sup>3</sup>)<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> = 4</div><div class=\"rv\">(c) 36<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup> = (6<sup>2</sup>)<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup> = 6</div><div class=\"rv\">(d) (−27)<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> = ((−3)<sup>3</sup>)<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> = −3</div></div></div>", "full": ""}, {"sub": "1.2", "n": 10, "N": 17, "kicker": "EXAMPLE 13", "title": "Fractional indices in other forms", "body": "<p class=\"sl-p\">1. Convert each of the following terms into the forms (<i>a</i><sup><i>m</i></sup>)<sup><span class=\"fr\"><span>1</span><span><i>n</i></span></span></sup> and (<i>a</i><sup><span class=\"fr\"><span>1</span><span><i>n</i></span></span></sup>)<sup><i>m</i></sup>. (a) 16<sup><span class=\"fr\"><span>3</span><span>4</span></span></sup> (b) 125<sup><span class=\"fr\"><span>2</span><span>3</span></span></sup></p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><div class=\"rv\">(a) 16<sup><span class=\"fr\"><span>3</span><span>4</span></span></sup> = (16<sup>3</sup>)<sup><span class=\"fr\"><span>1</span><span>4</span></span></sup> = (16<sup><span class=\"fr\"><span>1</span><span>4</span></span></sup>)<sup>3</sup></div><div class=\"rv\">(b) 125<sup><span class=\"fr\"><span>2</span><span>3</span></span></sup> = (125<sup>2</sup>)<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup> = (125<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup>)<sup>2</sup></div></div></div><p class=\"sl-p\">2. Convert each of the following terms into the forms <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i><sup><i>m</i></sup></span></span> and (<span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i></span></span>)<sup><i>m</i></sup>. (a) 16<sup><span class=\"fr\"><span>3</span><span>4</span></span></sup> (b) <i>p</i><sup><span class=\"fr\"><span>2</span><span>5</span></span></sup></p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><div class=\"rv\">(a) 16<sup><span class=\"fr\"><span>3</span><span>4</span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">4</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">16<sup>3</sup></span></span> = (<span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">4</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">16</span></span>)<sup>3</sup></div><div class=\"rv\">(b) <i>p</i><sup><span class=\"fr\"><span>2</span><span>5</span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">5</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>p</i><sup>2</sup></span></span> = (<span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">5</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>p</i></span></span>)<sup>2</sup></div></div></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">EXAMPLE 14</b> <div class=\"rv\">Calculate the value of each of the following terms. (a) 16<sup><span class=\"fr\"><span>3</span><span>4</span></span></sup> (b) 125<sup><span class=\"fr\"><span>2</span><span>3</span></span></sup></div></div><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">Method 1: 16<sup><span class=\"fr\"><span>3</span><span>4</span></span></sup> = (<span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">4</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">16</span></span>)<sup>3</sup> = 2<sup>3</sup> = 8</div><div class=\"rv\">Method 2: 16<sup><span class=\"fr\"><span>3</span><span>4</span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">4</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">16<sup>3</sup></span></span> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">4</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">4 096</span></span> = 8</div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">Method 1: 125<sup><span class=\"fr\"><span>2</span><span>3</span></span></sup> = (<span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">3</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">125</span></span>)<sup>2</sup> = 5<sup>2</sup> = 25</div><div class=\"rv\">Method 2: 125<sup><span class=\"fr\"><span>2</span><span>3</span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">3</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">125<sup>2</sup></span></span> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">3</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">15 625</span></span> = 25</div></div></div>", "full": ""}, {"sub": "1.2", "n": 11, "N": 17, "kicker": "EXAMPLE 15", "title": "Operations involving the laws of indices", "body": "<div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:15px;color:#A78BFA;border:1px solid #22304A;background:#0E1626\">Laws of indices</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\"><i>a</i><sup><i>m</i></sup> × <i>a</i><sup><i>n</i></sup> = <i>a</i><sup><i>m</i> + <i>n</i></sup> &nbsp; <i>a</i><sup><i>m</i></sup> ÷ <i>a</i><sup><i>n</i></sup> = <i>a</i><sup><i>m</i> − <i>n</i></sup> &nbsp; (<i>a</i><sup><i>m</i></sup>)<sup><i>n</i></sup> = <i>a</i><sup><i>mn</i></sup></td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:17px;font-weight:600;border:1px solid #22304A;vertical-align:top\"><i>a</i><sup>0</sup> = 1 &nbsp; <i>a</i><sup>−<i>n</i></sup> = <span class=\"fr\"><span>1</span><span><i>a</i><sup><i>n</i></sup></span></span> &nbsp; <i>a</i><sup><span class=\"fr\"><span>1</span><span><i>n</i></span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i></span></span> &nbsp; <i>a</i><sup><span class=\"fr\"><span><i>m</i></span><span><i>n</i></span></span></sup> = <span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i><sup><i>m</i></sup></span></span> = (<span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\"><i>n</i></sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>a</i></span></span>)<sup><i>m</i></sup></td></tr></tbody></table></div><p class=\"sl-p\">Simplify each of the following. (a) <span class=\"fr\"><span>(2<i>x</i><sup>3</sup>)<sup>2</sup> × (3<i>x</i><sup>−1</sup>)</span><span>6<i>x</i><sup>2</sup></span></span> (b) <span class=\"fr\"><span><span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">3</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\"><i>m</i><sup>2</sup></span></span> × <i>m</i><sup><span class=\"fr\"><span>1</span><span>3</span></span></sup></span><span><i>m</i><sup>−1</sup></span></span></p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= <span class=\"fr\"><span>4<i>x</i><sup>6</sup> × 3<i>x</i><sup>−1</sup></span><span>6<i>x</i><sup>2</sup></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>12</span><span>6</span></span> <i>x</i><sup>6 + (−1) − 2</sup></div><div class=\"rv\">= 2<i>x</i><sup>3</sup></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= <span class=\"fr\"><span><i>m</i><sup><span class=\"fr\"><span>2</span><span>3</span></span></sup> × <i>m</i><sup><span class=\"fr\"><span>1</span><span>3</span></span></sup></span><span><i>m</i><sup>−1</sup></span></span></div><div class=\"rv\">= <i>m</i><sup><span class=\"fr\"><span>2</span><span>3</span></span> + <span class=\"fr\"><span>1</span><span>3</span></span> − (−1)</sup></div><div class=\"rv\">= <i>m</i><sup>2</sup></div></div></div>", "full": ""}, {"sub": "1.2", "n": 12, "N": 17, "kicker": "EXAMPLE 16", "title": "Calculating values", "body": "<p class=\"sl-p\">Calculate the value of each of the following. (a) <span class=\"fr\"><span>81<sup><span class=\"fr\"><span>1</span><span>4</span></span></sup> × 25<sup><span class=\"fr\"><span>3</span><span>2</span></span></sup></span><span><span style=\"white-space:nowrap\"><sup style=\"margin-right:-3px\">2</sup>√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">9</span></span> × 5<sup>2</sup></span></span> (b) <span class=\"fr\"><span>8<sup><span class=\"fr\"><span>2</span><span>3</span></span></sup> × 27<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup></span><span>2<sup>3</sup> × 9<sup>−<span class=\"fr\"><span>1</span><span>2</span></span></sup></span></span></p><div class=\"sl-note\"><b>Tip:</b> Convert each base into its prime factors first.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= <span class=\"fr\"><span>(3<sup>4</sup>)<sup><span class=\"fr\"><span>1</span><span>4</span></span></sup> × (5<sup>2</sup>)<sup><span class=\"fr\"><span>3</span><span>2</span></span></sup></span><span>(3<sup>2</sup>)<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup> × 5<sup>2</sup></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>3<sup>1</sup> × 5<sup>3</sup></span><span>3<sup>1</sup> × 5<sup>2</sup></span></span></div><div class=\"rv\">= 3<sup>1 − 1</sup> × 5<sup>3 − 2</sup></div><div class=\"rv\">= 1 × 5 = 5</div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= <span class=\"fr\"><span>(2<sup>3</sup>)<sup><span class=\"fr\"><span>2</span><span>3</span></span></sup> × (3<sup>3</sup>)<sup><span class=\"fr\"><span>1</span><span>3</span></span></sup></span><span>2<sup>3</sup> × (3<sup>2</sup>)<sup>−<span class=\"fr\"><span>1</span><span>2</span></span></sup></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>2<sup>2</sup> × 3<sup>1</sup></span><span>2<sup>3</sup> × 3<sup>−1</sup></span></span></div><div class=\"rv\">= 2<sup>2 − 3</sup> × 3<sup>1 − (−1)</sup></div><div class=\"rv\">= 2<sup>−1</sup> × 3<sup>2</sup> = <span class=\"fr\"><span>9</span><span>2</span></span> = 4<span class=\"fr\"><span>1</span><span>2</span></span></div></div></div>", "full": ""}, {"sub": "1.2", "n": 13, "N": 17, "kicker": "EXAMPLE 17", "title": "Problem solving", "body": "<p class=\"sl-p\">Calculate the value of <span style=\"white-space:nowrap\">√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">2</span></span> × 18<sup><span class=\"fr\"><span>3</span><span>2</span></span></sup> ÷ 6 without using a calculator.</p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">Understanding the problem</b> <div class=\"rv\">Calculate the value of numbers in index form given in different bases.</div></div><div><b style=\"color:#A78BFA\">Planning a strategy</b> <div class=\"rv\">Convert each base into prime factors and calculate the value by applying the laws of indices.</div></div></div><div class=\"sl-note\"><b>Recall:</b> The common prime factors of 6 and 18 are 2 and 3.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#A78BFA\">Implementing the strategy</b> <div class=\"rv\"><span style=\"white-space:nowrap\">√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">2</span></span> × 18<sup><span class=\"fr\"><span>3</span><span>2</span></span></sup> ÷ 6</div><div class=\"rv\">= 2<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup> × (2 × 3 × 3)<sup><span class=\"fr\"><span>3</span><span>2</span></span></sup> ÷ (2 × 3)</div><div class=\"rv\">= 2<sup><span class=\"fr\"><span>1</span><span>2</span></span></sup> × 2<sup><span class=\"fr\"><span>3</span><span>2</span></span></sup> × 3<sup>3</sup> ÷ (2<sup>1</sup> × 3<sup>1</sup>)</div><div class=\"rv\">= 2<sup><span class=\"fr\"><span>1</span><span>2</span></span> + <span class=\"fr\"><span>3</span><span>2</span></span> − 1</sup> × 3<sup>3 − 1</sup></div><div class=\"rv\">= 2<sup>1</sup> × 3<sup>2</sup> = 18</div></div><div><b style=\"color:#A78BFA\">Making a conclusion</b> <div class=\"rv\"><span style=\"white-space:nowrap\">√<span style=\"display:inline-block;white-space:nowrap;border-top:2px solid currentColor;padding:2px 3px 0;line-height:1.15\">2</span></span> × 18<sup><span class=\"fr\"><span>3</span><span>2</span></span></sup> ÷ 6 = 18</div></div></div>", "full": ""}, {"sub": "1.2", "n": 14, "N": 17, "kicker": "EXAMPLE 18", "title": "Equations in index form", "body": "<p class=\"sl-p\">Calculate the value of <i>x</i> for the equation 2<sup><i>x</i></sup> × 4<sup><i>x</i> + 2</sup> ÷ 2<sup>7</sup> = 1.</p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">Understanding the problem</b> <div class=\"rv\">Calculate the value of the variable <i>x</i>, which is part of the index.</div></div><div><b style=\"color:#A78BFA\">Planning a strategy</b> <div class=\"rv\">This question is an equation. Hence, the value on the left side of the equation is equal to the value on the right side. Convert all the terms into index form with base 2.</div></div></div><div class=\"sl-note\"><b>Reminder:</b> If <i>a</i><sup><i>m</i></sup> = <i>a</i><sup><i>n</i></sup>, then <i>m</i> = <i>n</i>. If <i>a</i><sup><i>m</i></sup> = <i>b</i><sup><i>m</i></sup>, then <i>a</i> = <i>b</i>.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">Implementing the strategy</b> <div class=\"rv\">2<sup><i>x</i></sup> × 4<sup><i>x</i> + 2</sup> ÷ 2<sup>7</sup> = 1</div><div class=\"rv\">2<sup><i>x</i></sup> × 2<sup>2(<i>x</i> + 2)</sup> ÷ 2<sup>7</sup> = 2<sup>0</sup></div><div class=\"rv\">2<sup><i>x</i> + 2<i>x</i> + 4 − 7</sup> = 2<sup>0</sup></div><div class=\"rv\">3<i>x</i> − 3 = 0</div><div class=\"rv\"><i>x</i> = 1</div></div><div><b style=\"color:#A78BFA\">Making a conclusion</b> <div class=\"rv\">If 2<sup><i>x</i></sup> × 4<sup><i>x</i> + 2</sup> ÷ 2<sup>7</sup> = 1, then <i>x</i> = 1.</div></div><div><b style=\"color:#A78BFA\">Checking the answer</b> <div class=\"rv\">Substitute <i>x</i> = 1: 2<sup>1</sup> × 4<sup>3</sup> ÷ 2<sup>7</sup> = 2<sup>1 + 6 − 7</sup> = 2<sup>0</sup> = 1</div></div></div>", "full": ""}, {"sub": "1.2", "n": 15, "N": 17, "kicker": "EXAMPLE 19", "title": "Quadratic equations in index form", "body": "<p class=\"sl-p\">Calculate the possible values of <i>x</i> for the equation 2<sup><i>x</i><sup>2</sup></sup> × 2<sup><i>x</i></sup> = 2<sup>12</sup>.</p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">Understanding the problem</b> <div class=\"rv\">Calculate the values of <i>x</i>, which is part of the index.</div></div><div><b style=\"color:#A78BFA\">Planning a strategy</b> <div class=\"rv\">All the bases involved in the equation are the same.</div></div></div><div class=\"sl-note\"><b>Recall:</b> Solve quadratic equations using the factorisation method.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#A78BFA\">Implementing the strategy</b> <div class=\"rv\">2<sup><i>x</i><sup>2</sup></sup> × 2<sup><i>x</i></sup> = 2<sup>12</sup></div><div class=\"rv\">2<sup><i>x</i><sup>2</sup> + <i>x</i></sup> = 2<sup>12</sup></div><div class=\"rv\"><i>x</i><sup>2</sup> + <i>x</i> = 12</div><div class=\"rv\"><i>x</i><sup>2</sup> + <i>x</i> − 12 = 0</div><div class=\"rv\">(<i>x</i> − 3)(<i>x</i> + 4) = 0</div><div class=\"rv\"><i>x</i> − 3 = 0 or <i>x</i> + 4 = 0</div><div class=\"rv\"><i>x</i> = 3 or <i>x</i> = −4</div></div><div><b style=\"color:#A78BFA\">Making a conclusion</b> <div class=\"rv\">The possible values of <i>x</i> for the equation 2<sup><i>x</i><sup>2</sup></sup> × 2<sup><i>x</i></sup> = 2<sup>12</sup> are 3 and −4.</div></div></div>", "full": ""}, {"sub": "1.2", "n": 16, "N": 17, "kicker": "EXAMPLE 20", "title": "Simultaneous equations", "body": "<p class=\"sl-p\">Solve the following simultaneous equations. 9<sup><i>m</i></sup> × 3<sup><i>n</i></sup> = 3<sup>10</sup> and 2<sup><i>m</i></sup> ÷ 2<sup><i>n</i></sup> = 4</p><div class=\"sl-note\"><b>Recall:</b> Simultaneous linear equations in two variables can be solved using the substitution method or the elimination method.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><div class=\"rv\">9<sup><i>m</i></sup> × 3<sup><i>n</i></sup> = 3<sup>10</sup></div><div class=\"rv\">3<sup>2<i>m</i></sup> × 3<sup><i>n</i></sup> = 3<sup>10</sup></div><div class=\"rv\">2<i>m</i> + <i>n</i> = 10 ........ (1)</div><div class=\"rv\">2<sup><i>m</i></sup> ÷ 2<sup><i>n</i></sup> = 2<sup>2</sup></div><div class=\"rv\"><i>m</i> − <i>n</i> = 2 ........ (2)</div><div class=\"rv\">Equations (1) and (2) can be solved using the elimination method.</div><div class=\"rv\">(1) + (2): 3<i>m</i> = 12, <i>m</i> = 4</div><div class=\"rv\">Substitute <i>m</i> = 4 into (2): 4 − <i>n</i> = 2, <i>n</i> = 2</div><div class=\"rv\">Hence, <i>m</i> = 4 and <i>n</i> = 2</div></div></div>", "full": ""}, {"sub": "1.2", "n": 17, "N": 17, "kicker": "EXAMPLE 21", "title": "Problem solving", "body": "<p class=\"sl-p\">Danish and Ravi carried out two experiments to determine the values of the variables <i>x</i> and <i>y</i>. The equation obtained by Danish is 8(2<sup><i>x</i></sup>) = 4<sup><i>y</i></sup> while Ravi obtained the equation 5(25<sup><i>x</i></sup>) = 125<sup><i>y</i></sup> as the results of the experiments. Calculate the values of <i>x</i> and <i>y</i> that satisfy both experiments carried out by Danish and Ravi.</p><div class=\"sl-note\"><b>Tip:</b> The values of the variables <i>x</i> and <i>y</i> can be determined if you can solve both equations.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><div class=\"rv\">8(2<sup><i>x</i></sup>) = 4<sup><i>y</i></sup>: 2<sup>3</sup>(2<sup><i>x</i></sup>) = 2<sup>2<i>y</i></sup>, hence 3 + <i>x</i> = 2<i>y</i> ........ (1)</div><div class=\"rv\">5(25<sup><i>x</i></sup>) = 125<sup><i>y</i></sup>: 5<sup>1</sup>(5<sup>2<i>x</i></sup>) = 5<sup>3<i>y</i></sup>, hence 1 + 2<i>x</i> = 3<i>y</i> ........ (2)</div><div class=\"rv\">From (1): <i>x</i> = 2<i>y</i> − 3 ........ (3)</div><div class=\"rv\">Substitute (3) into (2): 1 + 2(2<i>y</i> − 3) = 3<i>y</i></div><div class=\"rv\">1 + 4<i>y</i> − 6 = 3<i>y</i>, <i>y</i> = 5</div><div class=\"rv\">Substitute <i>y</i> = 5 into (3): <i>x</i> = 2(5) − 3 = 7</div><div class=\"rv\">Hence, <i>x</i> = 7, <i>y</i> = 5</div></div></div>", "full": ""}];
